class Solution {
  public boolean checkPalindromeFormation(String a, String b) {
    return canSplit(a, b) || canSplit(b, a);
  }

  private boolean canSplit(String left, String right) {
    int i = 0, j = left.length() - 1;
    while (i < j && left.charAt(i) == right.charAt(j)) {
      i++;
      j--;
    }
    return isPalindrome(left, i, j) || isPalindrome(right, i, j);
  }

  private boolean isPalindrome(String value, int i, int j) {
    while (i < j) if (value.charAt(i++) != value.charAt(j--)) return false;
    return true;
  }
}
